-- 独立发布协调 schema v1；不创建第二份 session/run/approval 状态机。
CREATE TABLE delivery_leases(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,session_key TEXT NOT NULL,lifetime TEXT NOT NULL,owner_id TEXT NOT NULL,epoch BIGINT NOT NULL CHECK(epoch>0),expires_at_ms BIGINT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,session_key,lifetime));
CREATE TABLE event_outbox(cursor BIGSERIAL PRIMARY KEY,event_id TEXT NOT NULL UNIQUE,organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,session_key TEXT NOT NULL,lifetime TEXT NOT NULL,run_id TEXT NOT NULL,event_seq BIGINT NOT NULL CHECK(event_seq>0),payload_json TEXT NOT NULL,payload_digest TEXT NOT NULL,delivered BOOLEAN NOT NULL DEFAULT FALSE,claim_owner TEXT,claim_epoch BIGINT,UNIQUE(organization_id,tenant_id,project_id,agent_uid,run_id,event_seq),UNIQUE(organization_id,tenant_id,project_id,agent_uid,event_id,payload_digest));
CREATE INDEX outbox_pending ON event_outbox(organization_id,tenant_id,project_id,agent_uid,delivered,cursor);
CREATE TABLE publication_inbox(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,consumer TEXT NOT NULL,event_id TEXT NOT NULL,payload_digest TEXT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,consumer,event_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,event_id,payload_digest) REFERENCES event_outbox(organization_id,tenant_id,project_id,agent_uid,event_id,payload_digest));
CREATE FUNCTION prevent_outbox_rewrite() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable outbox payload'; END $$;
CREATE TRIGGER outbox_immutable BEFORE UPDATE OF event_id,organization_id,tenant_id,project_id,agent_uid,session_key,lifetime,run_id,event_seq,payload_json,payload_digest ON event_outbox FOR EACH ROW EXECUTE FUNCTION prevent_outbox_rewrite();
INSERT INTO coordination_migrations VALUES(1);
